        ],
        'sections' => [
            ['FSSAI licence types: Basic, State and Central', '<p>The licence you need depends mainly on your annual turnover and the kind of food business you run.</p><table><thead><tr><th>Type</th><th>Who it is for</th><th>Government fee per year</th></tr></thead><tbody>
